 void WorkspaceChanged(object? sender,PropertyChangedEventArgs e)
 {
  if(closed)return;
  if(e.PropertyName==nameof(workspace.LastViewingFilmCompletion)){
   var done=workspace.LastViewingFilmCompletion;
   if(done is null){pendingCompletedVariant=null;return;}
   if(done.Revision>consumedCompletionRevision){consumedCompletionRevision=done.Revision;if(done.Pinned){pendingCompletedVariant=done.ResultId;selection.Clear();selection.Add(done.ResultId);selected=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.VariantId==done.ResultId);}}
  }
  if(e.PropertyName==nameof(workspace.SessionPath)){pendingCompletedVariant=null;selection.Clear();selected=null;EndGesture(false);ExitDetail();InvalidateAvailability();}
  if(e.PropertyName==nameof(workspace.ActiveTarget))InvalidateAvailability();
  if(e.PropertyName==nameof(workspace.Layout))UpdateCards();
  if(e.PropertyName==nameof(workspace.ViewingFrames)){
   UpdateCards();if(pendingCompletedVariant is Guid id){var result=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.VariantId==id);if(result is not null){selected=result;pendingCompletedVariant=null;}}
   else if(selected is not null)selected=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.VariantId==selected.Item.VariantId)??selected;
  }
  if(e.PropertyName is nameof(workspace.ViewingStatus) or nameof(workspace.ViewingFailures)){if(!transientFeedback)status.Text=workspace.ViewingStatus;UpdateFixedList(fixedFilter);}
  if(e.PropertyName==nameof(workspace.ViewingTable)){ApplyViewport();UpdateCards();UpdateR55Light();UpdateFixedList(fixedFilter);}
  if(e.PropertyName is nameof(workspace.FilmTaskStatus) or nameof(workspace.IsFilmTaskRunning))UpdateFilmState();
  UpdateR55Chrome();
 }
 void UpdateR55Chrome(){filmSourceTitle.Text=selected?.Item.FrozenVariant.Name??"请选择照片";if(selected is not null&&!selection.Contains(selected.Item.VariantId))selected=null;emptyState.Visibility=workspace.ViewingTable.Items.Count==0?Visibility.Visible:Visibility.Collapsed;loadActions.Visibility=loadingBar.Visibility==Visibility.Visible||workspace.ViewingFailures.Count>0?Visibility.Visible:Visibility.Collapsed;contextBar.Visibility=selection.Count==0?Visibility.Collapsed:Visibility.Visible;infoPanel.Children.Clear();if(selected is not null){infoPanel.Children.Add(new TextBlock{Text=selected.Item.FrozenVariant.Name,FontSize=12,Margin=new(8)});infoPanel.Children.Add(new TextBlock{Text="固定变体 · "+selected.Image.PixelWidth+"×"+selected.Image.PixelHeight+" 代理",Margin=new(8)});}status.Visibility=transientFeedback||workspace.ViewingFailures.Count>0||workspace.ViewingStatus.Contains("取消")?Visibility.Visible:Visibility.Collapsed;if(selected is not null){var i=workspace.ViewingTable.Items.FirstOrDefault(i=>i.VariantId==selected.Item.VariantId);if(i is not null){var v=workspace.ViewingTable.Viewport;contextBar.Margin=new Thickness(Math.Clamp(i.X*v.Scale+v.X-scroll.HorizontalOffset,8,Math.Max(8,center.ActualWidth-210)),Math.Clamp((i.Y+150*i.Scale)*v.Scale+v.Y-scroll.VerticalOffset+5,48,Math.Max(48,center.ActualHeight-28)),0,0);}}UpdateSelectionBorders();}
