 async Task PreflightAsync(){var revision=++availabilityRevision;availabilityCancellation?.Cancel();var cancel=new CancellationTokenSource();availabilityCancellation=cancel;preflightPending=true;generate.IsEnabled=false;filmReason.Text=workspace.IsFilmTaskRunning?workspace.FilmTaskStatus:"检查来源…";var frame=selected;try{var reason=frame is null?"请选择照片":await workspace.ViewingFilmAvailabilityAsync(frame.Item,cancel.Token);if(closed||revision!=availabilityRevision||cancel.IsCancellationRequested||selected?.Item.VariantId!=frame?.Item.VariantId)return;unavailable=reason;preflightVariant=frame?.Item.VariantId;filmReason.Text=workspace.IsFilmTaskRunning?workspace.FilmTaskStatus:reason??"已有8位创意胶片";generate.IsEnabled=reason is null&&!workspace.IsFilmTaskRunning;}catch(Exception e)when(e is IOException or InvalidOperationException or NotSupportedException or OperationCanceledException or ArgumentException){if(!closed&&revision==availabilityRevision){unavailable=e.Message;filmReason.Text=e.Message;}}finally{if(revision==availabilityRevision)preflightPending=false;if(ReferenceEquals(availabilityCancellation,cancel))availabilityCancellation=null;cancel.Dispose();}}
