 void UpdateR55Light(){var state=workspace.ViewingTable;var sample=LightResponse.Sample((DateTime.UtcNow-lampStarted).TotalSeconds,state.PresentationLight,preferences.ReduceMotion||!SystemParameters.ClientAreaAnimation);board.Background=new SolidColorBrush(DisplayPanelColor(state.PresentationLight,state.Brightness,sample.Flare));board.Effect=state.PresentationLight?new DropShadowEffect{Color=Colors.White,BlurRadius=12,ShadowDepth=0,Opacity=.25+sample.Glow*.2}:null;foreach(var card in realized.Values){card.Effect=state.PresentationLight?null:new DropShadowEffect{BlurRadius=4,ShadowDepth=2,Opacity=.22};card.Opacity=state.PresentationLight?1:.98;}}
 // Versioned SDR board-only response: use pinned upstream PanelWhite at <=100%; use
 // remaining encoded display headroom above 100%. No photo/cache/export transform.
 internal static Color DisplayPanelColor(bool lit,double brightness,double flare=0){var basis=lit?Color.FromRgb(245,245,242):Color.FromRgb(227,217,191);var power=LightResponse.Power(brightness);var low=LightResponse.PanelWhite(power,0)/.9;var high=(LightResponse.PanelWhite(power,0)-.9)/(.948-.9);byte Channel(byte value){double result=power<=1?value*low:value+(255-value)*Math.Clamp(high,0,1)*.8;result+=(255-result)*Math.Clamp(flare,0,1)*.6;return(byte)Math.Clamp(Math.Round(result),0,255);}return Color.FromRgb(Channel(basis.R),Channel(basis.G),Channel(basis.B));}
